## Reference Solution

<details>
<summary>Click to reveal reference solution</summary>

```javascript
export function createAccumulator(initialValue = 0) {
    let total = initialValue;
    return {
        add(n) {
            total += n;
            return total;
        },
        get() {
            return total;
        }
    };
}

export function createPrivateVault(secretKey) {
    let currentKey = secretKey;
    return {
        unlock(key) {
            return key === currentKey;
        },
        changeKey(oldKey, newKey) {
            if (oldKey === currentKey) {
                currentKey = newKey;
                return true;
            }
            return false;
        }
    };
}

export function once(fn) {
    let executed = false;
    let cachedResult;
    return function(...args) {
        if (!executed) {
            executed = true;
            cachedResult = fn.apply(this, args);
        }
        return cachedResult;
    };
}
```
</details>

