## Reference Solution

<details>
<summary>Click to reveal reference solution</summary>

```javascript
export function createChild(parentObj, ownProps = {}) {
    const child = Object.create(parentObj);
    return Object.assign(child, ownProps);
}

export function getInheritedPropertyNames(obj) {
    const proto = Object.getPrototypeOf(obj);
    if (!proto || proto === Object.prototype) return [];
    return Object.keys(proto);
}

export function hasPrototype(target, proto) {
    if (!target || !proto) return false;
    return proto.isPrototypeOf(target);
}
```
</details>

