    assert.equal(dog.name, 'Rex');
    assert.equal(dog.sound, 'Bark'); // inherited
    assert.equal(Object.hasOwn(dog, 'name'), true);
    assert.equal(Object.hasOwn(dog, 'sound'), false);
});

