## Reference Solution

<details>
<summary>Click to reveal reference solution</summary>

```javascript
export async function fetchUserAndPosts(userId, fetchUserFn, fetchPostsFn) {
    const [user, posts] = await Promise.all([
        fetchUserFn(userId),
        fetchPostsFn(userId)
    ]);
    return { user, posts };
}

export async function retryAsync(asyncFn, retries = 3) {
    let lastError;
    for (let i = 0; i < retries; i++) {
        try {
            return await asyncFn();
        } catch (err) {
            lastError = err;
        }
    }
    throw lastError;
}

export async function mapConcurrent(items, asyncMapper) {
    return Promise.all(items.map(asyncMapper));
}
```
</details>

