        if (attempts < 2) throw new Error('Temporary failure');
        return 'success';
    };

    const res = await retryAsync(flakey, 3);
    assert.equal(res, 'success');
    assert.equal(attempts, 2);
});

test('retryAsync throws last error if all attempts fail', async () => {
    const alwaysFails = async () => { throw new Error('Permanent crash'); };
    await assert.rejects(
        () => retryAsync(alwaysFails, 2),
        { message: 'Permanent crash' }
    );
});

test('mapConcurrent transforms items concurrently', async () => {
    const double = async (x) => x * 2;
    const results = await mapConcurrent([1, 2, 3], double);
